-- Disposable service-role fixture; runner supplies transaction and rollback.
do $test$
declare token text:=repeat('a',64); other_token text:=repeat('b',64); r jsonb; again jsonb; op text; faculty uuid:=gen_random_uuid(); faculty_token text:=repeat('c',64);
begin
 if to_regprocedure('public.navrang_report_operations(text,jsonb,text)') is null then raise exception 'Missing report operation RPC';end if;
 insert into navrang_private.sessions(hash,role,expires_at) values(token,'admin',clock_timestamp()+interval '1 hour'),(other_token,'admin',clock_timestamp()+interval '1 hour');
 r:=public.navrang_report_operations('prepare-export','{"kind":"all","format":"csv","requestId":"fixture-1"}',token);
 if r ? 'error' or not r ? 'rows' or not r ? 'operationId' then raise exception 'Preparation failed: %',r;end if;
 op:=r->>'operationId';
 again:=public.navrang_report_operations('prepare-export','{"kind":"all","format":"csv","requestId":"fixture-1"}',token);
 if again->>'operationId' is distinct from op then raise exception 'Replay changed operation';end if;
 r:=public.navrang_report_operations('prepare-export','{"kind":"all","format":"xlsx","requestId":"fixture-1"}',token);
 if r->>'status' is distinct from '409' then raise exception 'Conflicting replay accepted';end if;
 r:=public.navrang_report_operations('outcome',jsonb_build_object('operationId',op,'outcome','saved'),token);
 if r->>'status' is distinct from '409' then raise exception 'Saved before initiated accepted';end if;
 r:=public.navrang_report_operations('outcome',jsonb_build_object('operationId',op,'outcome','initiated'),other_token);
 if r->>'status' is distinct from '404' then raise exception 'Cross-session receipt accepted';end if;
 r:=public.navrang_report_operations('outcome',jsonb_build_object('operationId',op,'outcome','initiated'),token);
 if r->>'outcome' is distinct from 'initiated' then raise exception 'Initiated rejected: %',r;end if;
 r:=public.navrang_report_operations('outcome',jsonb_build_object('operationId',op,'outcome','saved'),token);
 if r->>'outcome' is distinct from 'saved' or r->>'deviceReported' is distinct from 'true' then raise exception 'Saved rejected: %',r;end if;
 again:=public.navrang_report_operations('outcome',jsonb_build_object('operationId',op,'outcome','saved'),token);
 if again is distinct from r then raise exception 'Outcome replay differs';end if;
 r:=public.navrang_report_operations('outcome',jsonb_build_object('operationId',op,'outcome','failed'),token);
 if r->>'status' is distinct from '409' then raise exception 'Terminal conflict accepted';end if;
 r:=public.navrang_report_operations('prepare-summary','{"requestId":"summary-1"}',token);
 if r ? 'error' or not r ? 'stats' then raise exception 'Summary missing: %',r;end if;
 op:=r->>'operationId';
 r:=public.navrang_report_operations('outcome',jsonb_build_object('operationId',op,'outcome','cancelled'),token);
 if r->>'outcome' is distinct from 'cancelled' then raise exception 'Prepared cancellation rejected';end if;
 update navrang_private.report_operations set expires_at=clock_timestamp()-interval '1 second' where id=op::uuid;
 r:=public.navrang_report_operations('outcome',jsonb_build_object('operationId',op,'outcome','cancelled'),token);
 if r->>'status' is distinct from '410' then raise exception 'Expired receipt accepted';end if;
 insert into navrang_private.checkers(id,name,method,google_id,email,active,name_confirmed,scanner_enabled,helpdesk_enabled,selected_station)
 values(faculty,'Fixture faculty','google',gen_random_uuid(),'reports-fixture@example.invalid',true,true,false,false,'');
 insert into navrang_private.report_grants(checker_id,enabled) values(faculty,true);
 insert into navrang_private.sessions(hash,role,checker_id,expires_at) values(faculty_token,'checker',faculty,clock_timestamp()+interval '1 hour');
 r:=public.navrang_report_operations('prepare-export','{"kind":"attended","format":"xlsx","requestId":"faculty-1"}',faculty_token);
 if r ? 'error' or not r ? 'rows' then raise exception 'Faculty preparation denied: %',r;end if;
 op:=r->>'operationId';
 r:=public.navrang_report_operations('outcome',jsonb_build_object('operationId',op,'outcome','initiated'),token);
 if r->>'status' is distinct from '404' then raise exception 'Cross-account receipt accepted';end if;
 update navrang_private.report_grants set enabled=false where checker_id=faculty;
 r:=public.navrang_report_operations('outcome',jsonb_build_object('operationId',op,'outcome','failed'),faculty_token);
 if r->>'status' is distinct from '403' then raise exception 'Revoked faculty receipt accepted';end if;
 r:=public.navrang_report_operations('prepare-summary','{"requestId":"revoked-1"}',faculty_token);
 if r->>'status' is distinct from '403' then raise exception 'Revoked faculty preparation accepted';end if;
 update navrang_private.report_grants set enabled=true where checker_id=faculty;
 r:=public.navrang_report_operations('outcome',jsonb_build_object('operationId',op,'outcome','failed'),faculty_token);
 if r->>'outcome' is distinct from 'failed' then raise exception 'Prepared failure rejected';end if;
 update navrang_private.sessions set expires_at=clock_timestamp()-interval '1 second' where hash=faculty_token;
 r:=public.navrang_report_operations('outcome',jsonb_build_object('operationId',op,'outcome','failed'),faculty_token);
 if r->>'status' is distinct from '401' then raise exception 'Expired session accepted';end if;
 r:=public.navrang_report_operations('prepare-export','{"kind":"all","format":"pdf","requestId":"bad-1"}',token);
 if r->>'status' is distinct from '400' then raise exception 'Invalid export format accepted';end if;
 r:=public.navrang_report_operations('prepare-summary','{"requestId":"bad-2","filename":"private.csv"}',token);
 if r->>'status' is distinct from '400' then raise exception 'Extra filesystem field accepted';end if;
 if has_table_privilege('anon','navrang_private.report_operations','SELECT') or has_table_privilege('authenticated','navrang_private.report_operations','SELECT') then raise exception 'Public metadata access granted';end if;
 if has_function_privilege('anon','public.navrang_report_operations(text,jsonb,text)','EXECUTE') or has_function_privilege('authenticated','public.navrang_report_operations(text,jsonb,text)','EXECUTE') then raise exception 'Public execution granted';end if;
end;
$test$;
